/* Visual prototype only. In-memory UI states, no API calls, auth, uploads or persistence. */
const $ = (q,root=document)=>root.querySelector(q);
const $$ = (q,root=document)=>[...root.querySelectorAll(q)];
const esc = value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = (name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${NEX.icons[name]||NEX.icons.file}</svg>`;
const mark=()=>'<span class="brand-mark"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 17V7h3l8 10h3V7M5 7l14 10" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg></span>';
const S={role:'owner',view:'normal',projectTab:'conversations',projectFilter:'all',projectSearch:'',librarySearch:'',libraryProvider:'all',librarySource:'all',integrationTab:'api',provider:'claude',importProvider:'openai',importStep:1,importReady:false,settingsTab:'workspace',employeeSearch:'',newMessages:{},mobile:false,projectId:'p1',demoCounter:0};
const me=()=>NEX.people.find(p=>p.id===(S.role==='owner'?'owner':'linh'));
const person=id=>NEX.people.find(p=>p.id===id)||NEX.people[0];
const project=id=>NEX.projects.find(p=>p.id===id)||NEX.projects[0];
const provider=id=>NEX.providers.find(p=>p.id===id)||NEX.providers[0];
const canRead=p=>S.role==='owner'||p.owner===me().id||p.members.includes(me().id);
const canWrite=p=>p.owner===me().id||p.write.includes(me().id);
const visibleProjects=()=>NEX.projects.filter(canRead);
const visibleChats=()=>NEX.conversations.filter(c=>canRead(project(c.project)));
const avatar=(id,cls='')=>`<span class="avatar ${esc(id)} ${cls}" title="${esc(person(id).name)}">${esc(person(id).initials)}</span>`;
const symbol=(id,large=false)=>`<span class="provider-symbol ${esc(id)} ${large?'large':''}" aria-hidden="true">${provider(id).letter}</span>`;
const money=n=>'$'+Number(n).toFixed(2);
const pill=(text,cls='')=>`<span class="pill ${cls}">${text}</span>`;
const btn=(label,action,ic='',cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${ic?icon(ic):''}${label}</button>`;
const ib=(ic,label,action,extra='')=>`<button class="icon-button" aria-label="${label}" title="${label}" data-action="${action}" ${extra}>${icon(ic)}</button>`;
const route=()=>location.hash.replace(/^#\/?/,'').split('/').filter(Boolean);
const go=path=>{if(location.hash===`#/${path}`)render();else location.hash='/'+path;};
const titles={overview:'Tổng quan',projects:'Dự án',project:'Chi tiết dự án',chat:'Hội thoại',library:'Kho hội thoại',integrations:'Nguồn AI',team:'Nhân viên',usage:'Chi phí sử dụng',imports:'Nhập dữ liệu',settings:'Cài đặt',audit:'Nhật ký hoạt động',login:'Đăng nhập'};
let toastTimer,typingTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function notice(text,type=''){return `<div class="info-banner ${type}">${icon(type==='red'||type==='amber'?'alert':'shield')}<span class="flex">${text}</span></div>`;}
function heading(title,description,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${actions}</div>`;}
function navLink(id,label,ic,count=''){const r=route()[0]||'overview';const active=r===id||(id==='projects'&&r==='project');return `<a class="nav-item ${active?'active':''}" href="#/${id}" ${active?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${count?`<span class="nav-count">${count}</span>`:''}</a>`;}
function sidebar(){return `<aside class="sidebar ${S.mobile?'open':''}" aria-label="Điều hướng chính"><a href="#/overview" class="brand">${mark()}<span>nex<span style="font-weight:400"> ai hub</span></span></a><button class="workspace-select" data-action="workspace"><span class="workspace-logo">N</span><span class="workspace-info text-left"><strong>NexMO Workspace</strong><br><small>Không gian công việc</small></span>${icon('down')}</button><nav><div class="nav-group"><div class="nav-label">KHÔNG GIAN LÀM VIỆC</div>${navLink('overview','Tổng quan','grid')}${navLink('projects',S.role==='owner'?'Tất cả dự án':'Dự án của tôi','folder',visibleProjects().length)}${navLink('library','Kho hội thoại','library')}</div><div class="nav-group"><div class="nav-label">${S.role==='owner'?'QUẢN TRỊ':'CÁ NHÂN'}</div>${S.role==='owner'?navLink('integrations','Nguồn AI','plug')+navLink('team','Nhân viên','people','5'):''}${navLink('usage',S.role==='owner'?'Chi phí sử dụng':'Sử dụng của tôi','chart')}${S.role==='owner'?navLink('imports','Nhập dữ liệu','upload')+navLink('audit','Nhật ký hoạt động','activity'):''}</div></nav><div class="sidebar-bottom"><div class="sidebar-budget"><div class="row between"><span class="label">Ngân sách tháng 11</span>${icon('wallet')}</div><div class="row between mt12"><strong>${S.role==='owner'?'$65.40':'$18.60'}</strong><span class="tiny muted">/ ${S.role==='owner'?'$150':'$30'}</span></div><div class="track"><span style="width:${S.role==='owner'?44:62}%"></span></div><div class="tiny muted" style="font-size:10px">Số liệu mẫu để xem giao diện</div></div>${navLink('settings','Cài đặt','settings')}<button class="nav-item full" data-action="guide">${icon('help')}<span>Hướng dẫn prototype</span></button><div class="sidebar-account">${avatar(me().id)}<div class="name"><strong>${me().name}</strong><br><small>${S.role==='owner'?'Chủ doanh nghiệp':'Nhân viên'}</small></div>${ib('logout','Xem màn hình đăng nhập','login')}</div></div></aside>`;}
function shell(content){const r=route()[0]||'overview';return `<div class="shell"><button class="mobile-scrim ${S.mobile?'open':''}" data-action="menu" aria-label="Đóng điều hướng"></button>${sidebar()}<div class="app-body"><header class="topbar"><div class="row gap6">${ib('menu','Mở điều hướng','menu','data-mobile-menu')}<div class="breadcrumbs"><span class="breadcrumb-parent">Không gian làm việc</span><span class="breadcrumb-parent">/</span><span class="current">${titles[r]||'Tổng quan'}</span></div></div><div class="top-actions"><button class="search-trigger" data-action="search" aria-label="Tìm trong không gian làm việc">${icon('search')}<span>Tìm trong không gian làm việc...</span><kbd>⌘ K</kbd></button>${ib('bell','Thông báo','notifications')}<span class="desktop-only" style="height:20px;border-left:1px solid var(--line)"></span>${avatar(me().id)}</div></header><div class="prototype-bar"><span class="prototype-label">PROTOTYPE · DỮ LIỆU MINH HỌA</span><div class="demo-controls"><label class="sr-only" for="role-select">Vai trò xem thử</label><select id="role-select" aria-label="Vai trò xem thử"><option value="owner" ${S.role==='owner'?'selected':''}>Xem: Chủ doanh nghiệp</option><option value="employee" ${S.role==='employee'?'selected':''}>Xem: Nhân viên Linh</option></select><button class="demo-link" data-action="guide">Các màn hình</button></div></div><main id="main" class="content" tabindex="-1">${content}</main></div></div>`;}
function projectCard(p){return `<a href="#/project/${p.id}" class="project-card"><div class="row between"><span class="project-icon ${p.color}">${icon(p.icon)}</span>${pill(p.tag)}</div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><div class="project-meta"><span>${icon('chat')}${p.chats} hội thoại</span><span>${icon('file')}${p.files} tài liệu</span></div><footer><div class="avatar-group">${[p.owner,...p.members].slice(0,3).map(id=>avatar(id,'sm')).join('')}${p.members.length>2?`<span class="avatar sm">+${p.members.length-2}</span>`:''}</div><span>${p.date}</span></footer></a>`;}
function conversationRow(c,details=false){return `<a class="conversation-item" href="#/chat/${c.id}">${symbol(c.provider)}<div class="conversation-text"><div class="conversation-title">${esc(c.title)}</div><div class="conversation-sub"><span>${esc(project(c.project).name)}</span><span>·</span><span>${person(c.author).name}</span>${details?`<span>· ${c.messages} tin nhắn</span>`:''}</div></div><time>${c.time}</time>${details?icon('chevron'):''}</a>`;}
function metric(label,value,ic,sub=''){return `<div class="metric"><div class="metric-top">${icon(ic)}${label}</div><div class="metric-number">${value}${sub?`<small>${sub}</small>`:''}</div></div>`;}
function stateContent(){if(S.view==='empty')return `<div class="panel empty"><div class="empty-icon">${icon('folder')}</div><h2>Một khởi đầu mới</h2><p>Tạo dự án đầu tiên để sắp xếp ý tưởng, tài liệu và những cuộc trò chuyện với AI.</p>${btn('Tạo dự án đầu tiên','new-project','plus','primary')}${btn('Về dữ liệu mẫu','normal','','ghost')}</div>`;if(S.view==='loading')return `<div role="status" aria-label="Đang tải dữ liệu mẫu"><div class="skeleton" style="width:38%;height:30px"></div><div class="skeleton" style="width:64%"></div><div class="project-grid mt24">${[1,2,3].map(()=>'<div class="panel skeleton-card"><div class="skeleton" style="width:35%;height:30px"></div><div class="skeleton"></div><div class="skeleton" style="width:75%"></div></div>').join('')}</div><div class="mt24">${btn('Kết thúc trạng thái tải','normal','','soft')}</div></div>`;if(S.view==='error')return `<div class="panel empty"><div class="empty-icon">${icon('alert')}</div><h2>Chưa thể tải dữ liệu</h2><p>Kết nối tạm thời bị gián đoạn. Các hội thoại đã lưu của bạn vẫn được giữ nguyên.</p>${btn('Thử lại','normal','refresh','primary')}<p class="tiny">Màn hình lỗi minh họa</p></div>`;return '';}
function overview(){return `${heading(`Chào buổi sáng, ${S.role==='owner'?'Minh':'Linh'}.`,'Mọi AI, mọi dự án. Cùng một không gian làm việc.','<div class="date">Thứ Ba, 03 tháng 11, 2026</div>')}${stateContent()||`<div class="welcome-grid"><section class="start-panel"><div class="eyebrow">KHÔNG GIAN CHO Ý TƯỞNG TIẾP THEO</div><h2>Bạn muốn bắt đầu từ đâu?</h2><p>Một câu hỏi nhỏ có thể mở ra một hướng đi mới.</p><div class="quick-composer"><label for="quick-prompt" class="sr-only">Câu hỏi mới</label><textarea id="quick-prompt" placeholder="Hỏi, tìm hiểu hoặc cùng AI phát triển ý tưởng...">${esc(S.quickDraft||'')}</textarea><div class="quick-bottom"><div class="provider-choices">${NEX.providers.slice(0,3).map(p=>`<button class="provider-choice ${S.provider===p.id?'active':''}" data-action="quick-provider" data-id="${p.id}">${symbol(p.id)}${p.name}</button>`).join('')}</div><button class="send-button" data-action="quick-chat" aria-label="Bắt đầu hội thoại">${icon('up')}</button></div></div><div class="hero-foot"><span>${icon('shield')}Ngữ cảnh riêng theo dự án</span><span>${icon('check')}Hội thoại được lưu tự động</span></div></section><aside class="budget-hero"><div class="row between"><div class="eyebrow">${S.role==='owner'?'NGÂN SÁCH THÁNG 11':'HẠN MỨC CỦA BẠN'}</div>${icon('chart')}</div><div class="hero-money">${S.role==='owner'?'$84.60':'$11.40'} <small>còn lại</small></div><div class="track"><span style="width:${S.role==='owner'?44:62}%"></span></div><div class="budget-stats"><span>Đã sử dụng ${S.role==='owner'?'$65.40':'$18.60'}</span><span>${S.role==='owner'?44:62}%</span></div><a class="budget-link" href="#/usage"><span>Xem chi tiết sử dụng</span>${icon('arrow')}</a></aside></div><div class="metrics-strip">${metric('Dự án đang hoạt động',visibleProjects().length,'folder')}${metric('Hội thoại trong tháng',S.role==='owner'?'110':'74','chat','+12 tuần này')}${metric('Thành viên',S.role==='owner'?'6':'3','people',S.role==='owner'?'5 nhân viên':'dự án cộng tác')}${metric('Nguồn AI sẵn sàng','3 / 4','plug')}</div><section><div class="section-heading"><h2>Tiếp tục công việc <span>Dự án gần đây</span></h2><a class="text-link" href="#/projects">Tất cả dự án ${icon('arrow')}</a></div><div class="project-grid preview">${visibleProjects().slice(0,3).map(projectCard).join('')}</div></section><div class="bottom-grid"><section class="panel panel-padding"><div class="section-heading"><h2>Hội thoại gần đây</h2><a class="text-link" href="#/library">Xem tất cả ${icon('arrow')}</a></div>${visibleChats().slice(0,4).map(c=>conversationRow(c)).join('')}</section><aside class="panel panel-padding status-panel"><div class="section-heading"><h2>Nguồn AI</h2>${icon('plug')}</div><div class="status-list">${NEX.providers.map(p=>`<div class="provider-status-row">${symbol(p.id)}<span>${p.name}</span>${pill(p.id==='meta'?'Chờ xác minh':'Sẵn sàng',p.id==='meta'?'amber dot':'green dot')}</div>`).join('')}</div><div class="status-note">Trạng thái kết nối minh họa. Prototype chưa kết nối dịch vụ AI.</div></aside></div>`}`;}
function projectsPage(){let items=visibleProjects().filter(p=>!S.projectSearch||`${p.name} ${p.description}`.toLocaleLowerCase('vi').includes(S.projectSearch.toLocaleLowerCase('vi')));if(S.projectFilter==='mine')items=items.filter(p=>p.owner===me().id);if(S.projectFilter==='shared')items=items.filter(p=>p.owner!==me().id&&p.members.includes(me().id));return `${heading(S.role==='owner'?'Tất cả dự án':'Dự án của tôi','Sắp xếp ý tưởng và hội thoại theo từng mục tiêu công việc.',btn('Tạo dự án','new-project','plus','primary'))}${notice(S.role==='owner'?'Bạn có quyền xem toàn bộ dự án công việc trong NexMO. Quyền đóng góp được cấp riêng theo dự án.':'Dự án công việc — chủ doanh nghiệp có quyền xem nội dung. Nhân viên khác chỉ thấy khi được chia sẻ.')}<div class="toolbar"><div class="tabs">${[['all','Tất cả',visibleProjects().length],['mine','Của tôi',visibleProjects().filter(p=>p.owner===me().id).length],['shared','Được chia sẻ',visibleProjects().filter(p=>p.owner!==me().id&&p.members.includes(me().id)).length]].map(([id,name,count])=>`<button class="tab ${S.projectFilter===id?'active':''}" data-action="project-filter" data-id="${id}">${name}<span class="count">${count}</span></button>`).join('')}</div><div class="row"><div class="input-icon">${icon('search')}<input class="input" id="project-search" aria-label="Tìm dự án" placeholder="Tìm dự án..." value="${esc(S.projectSearch)}"></div></div></div>${stateContent()||(items.length?`<div class="project-grid">${items.map(projectCard).join('')}</div>`:emptySearch())}`;}
function emptySearch(){return `<div class="panel empty"><div class="empty-icon">${icon('search')}</div><h2>Chưa tìm thấy kết quả</h2><p>Thử một từ khóa khác hoặc bỏ bộ lọc để xem thêm nội dung.</p>${btn('Bỏ bộ lọc','clear-filters','refresh','soft')}</div>`;}
function denied(){return `<div class="panel empty"><div class="empty-icon">${icon('lock')}</div><h2>Bạn chưa có quyền truy cập</h2><p>Dự án này chưa được chia sẻ với bạn. Bạn có thể liên hệ chủ dự án để được cấp quyền.</p><a class="btn primary" href="#/projects">Về dự án của tôi</a></div>`;}
function projectPage(id){const p=project(id);if(!canRead(p))return denied();const writable=canWrite(p);return `${heading(esc(p.name),`Dự án của ${person(p.owner).name} · Cập nhật ${p.date.toLowerCase()}`,`<div class="row">${btn('Chia sẻ','share','people','',`data-id="${p.id}"`)}${writable?btn('Hội thoại mới','project-chat','plus','primary',`data-id="${p.id}"`):pill('Chỉ xem','blue')}</div>`)}<div class="project-detail-grid"><div><p class="project-description">${esc(p.description)}</p>${notice(writable?'Dự án công việc — chủ doanh nghiệp có quyền xem nội dung.':'Bạn đang xem dự án. Cần quyền đóng góp để tạo hoặc tiếp tục hội thoại.')}<div class="detail-tabs">${[['conversations','Hội thoại','chat'],['files','Tài liệu','file'],['members','Thành viên','people']].map(([key,label,ic])=>`<button class="detail-tab ${S.projectTab===key?'active':''}" data-action="project-tab" data-id="${key}">${icon(ic)}${label}</button>`).join('')}</div><div class="panel mt24">${S.projectTab==='conversations'?`<div class="detail-list">${NEX.conversations.filter(c=>c.project===p.id).map(c=>conversationRow(c,true)).join('')||'<div class="empty"><h3>Chưa có hội thoại</h3><p>Bắt đầu từ một câu hỏi cho dự án này.</p></div>'}</div>`:S.projectTab==='files'?`<div class="panel-padding">${['Tổng quan nghiên cứu.pdf','Phản hồi khách hàng.xlsx','Ghi chú dự án.md'].map((f,i)=>`<div class="file-row"><div class="file-icon">${icon('file')}</div><div class="file-info"><strong>${f}</strong><p>${['2.4 MB','840 KB','12 KB'][i]} · ${person(p.owner).name} · Tệp mẫu</p></div>${ib('eye','Xem tài liệu mẫu','file-preview',`data-id="${i}"`)}</div>`).join('')}</div>`:`<div class="panel-padding">${[p.owner,...p.members].map(uid=>`<div class="file-row">${avatar(uid)}<div class="file-info"><strong>${person(uid).name}</strong><p>${person(uid).email}</p></div>${pill(uid===p.owner?'Chủ dự án':p.write.includes(uid)?'Đóng góp':'Chỉ xem',uid===p.owner?'green':'')}</div>`).join('')}<div class="info-banner">${icon('eye')}Chủ doanh nghiệp luôn có quyền xem dự án công việc.</div></div>`}</div></div><aside class="panel panel-padding project-side"><h3>Thông tin dự án</h3><div class="definition"><div class="definition-row"><span>Chủ dự án</span><span class="row gap6">${avatar(p.owner,'sm')}${person(p.owner).name}</span></div><div class="definition-row"><span>Phân loại</span>${pill(p.tag)}</div><div class="definition-row"><span>Ngày tạo</span><span>20/10/2026</span></div><div class="definition-row"><span>Hội thoại</span><strong>${p.chats}</strong></div><div class="definition-row"><span>Tài liệu</span><strong>${p.files}</strong></div>${S.role==='owner'?`<div class="definition-row"><span>Chi phí mẫu</span><strong>${money(p.cost)}</strong></div>`:''}</div><div class="divider"></div><h3>AI trong dự án</h3><div class="row mt12">${NEX.providers.slice(0,3).map(pr=>symbol(pr.id)).join('')}<span class="tiny muted">3 kết nối chung</span></div><div class="divider"></div><p class="small muted">Ngữ cảnh được tách theo từng hội thoại. Chỉ tài liệu bạn chọn mới được gửi cho AI.</p></aside></div>`;}

function render(){
  const [page='overview',id]=route();
  const pages={overview,projects:projectsPage,project:()=>projectPage(id)};
  if(typeof chatPage==='function')pages.chat=()=>chatPage(id);
  if(typeof libraryPage==='function')pages.library=libraryPage;
  if(typeof integrationsPage==='function')pages.integrations=integrationsPage;
  if(typeof teamPage==='function')pages.team=teamPage;
  if(typeof usagePage==='function')pages.usage=usagePage;
  if(typeof importsPage==='function')pages.imports=importsPage;
  if(typeof settingsPage==='function')pages.settings=settingsPage;
  if(typeof auditPage==='function')pages.audit=auditPage;
  const adminOnly=['integrations','team','imports','audit'];
  let content=S.role!=='owner'&&adminOnly.includes(page)?denied():pages[page]?pages[page]():`${heading(titles[page]||'Prototype','Màn hình này đang được hoàn thiện trong bản xem trước.')}<div class="panel empty"><div class="empty-icon">${icon('edit')}</div><h2>Đang dựng giao diện chi tiết</h2><p>Bạn có thể xem Tổng quan và Dự án trong lúc các màn hình khác được hoàn thiện.</p><a class="btn primary" href="#/overview">Về tổng quan</a></div>`;
  $('#app').innerHTML=page==='login'&&typeof loginPage==='function'?loginPage():shell(content);
  document.title=`${titles[page]||'Prototype'} · Nex AI Hub`;
}
window.addEventListener('hashchange',()=>{S.mobile=false;if(route()[1]!=='new')S.draft='';render();window.scrollTo(0,0);});
document.addEventListener('click',e=>{
  if(e.target.closest('.skip-link')){e.preventDefault();$('#main')?.focus();return;}
  const el=e.target.closest('[data-action]');if(!el)return;
  const a=el.dataset.action,id=el.dataset.id;
  if(typeof dispatch==='function'&&dispatch(a,id,el,e))return;
  if(a==='menu'){S.mobile=!S.mobile;render();}
  else if(a==='project-tab'){S.projectTab=id;render();}
  else if(a==='project-filter'){S.projectFilter=id;render();}
  else if(a==='quick-provider'){S.quickDraft=$('#quick-prompt')?.value||'';S.provider=id;render();}
  else if(a==='login')go('login');
  else if(a==='normal'){S.view='normal';render();}
  else if(a==='clear-filters'){S.projectSearch='';S.projectFilter='all';S.librarySearch='';S.libraryProvider='all';S.librarySource='all';render();}
  else toast('Thao tác này đang hiển thị ở chế độ xem trước.');
});
document.addEventListener('change',e=>{if(e.target.id==='role-select'){S.role=e.target.value;S.view='normal';S.draft='';render();}});
document.addEventListener('input',e=>{if(e.target.id==='project-search'){const value=e.target.value,pos=e.target.selectionStart;S.projectSearch=value;render();const input=$('#project-search');input.focus();input.setSelectionRange(pos,pos);}});
render();
